(()=>{if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('ed-entered');observer.unobserve(e.target)}}),{threshold:.04,rootMargin:'0px 0px -20px 0px'});document.querySelectorAll('.ed-figure').forEach(el=>{el.classList.add('ed-reveal');observer.observe(el)})})();
